class CustomSearchEngine{constructor(){this.docs=[];this.idf={};self.vectors=[];this.isLoaded=!1}async loadIndex(b="search_index.json"){try{let d=await (await fetch(b)).json();this.docs=d.docs;this.idf=d.idf;this.vectors=d.vectors;this.isLoaded=!0;console.log(`\u2705 \u30d5\u30eb\u30b9\u30af\u30e9\u30c3\u30c1\u691c\u7d22\u30a8\u30f3\u30b8\u30f3: ${this.docs.length} \u4ef6\u306e\u7528\u8a9e\u30a4\u30f3\u30c7\u30c3\u30af\u30b9\u3092\u30ed\u30fc\u30c9\u5b8c\u4e86`);return!0}catch(d){return console.error("\u274c \u30a4\u30f3\u30c7\u30c3\u30af\u30b9\u30c7\u30fc\u30bf\u306e\u30ed\u30fc\u30c9\u306b\u5931\u6557:",
d),!1}}tokenize(b){b=b.toLowerCase().replace(/[^\w\s]/g,"");var d=b.split(/\s+/).filter(c=>c.length>0),f=[];for(let c=0;c<b.length-1;c++){let g=b.substring(c,c+2);/\s/.test(g)||f.push(g)}return d.concat(f)}search(b,d=10){if(!this.isLoaded||!b.trim())return[];var f=this.tokenize(b);if(f.length===0)return[];var c={};f.forEach(a=>{c[a]=(c[a]||0)+1});var g={},k=0;Object.keys(c).forEach(a=>{var e=c[a]/f.length*(this.idf[a]||1);g[a]=e;k+=e*e});var r=k>0?Math.sqrt(k):1,l={};Object.keys(g).forEach(a=>{l[a]=
g[a]/r});var m=[],p=b.toLowerCase();this.docs.forEach((a,e)=>{var q=this.vectors[e]||{},h=0;Object.keys(l).forEach(n=>{q[n]&&(h+=l[n]*q[n])});e=a.name.toLowerCase();var t=a.summary.toLowerCase();e.includes(p)?h+=2:t.includes(p)&&(h+=.5);h>.05&&m.push({doc:a,score:h})});m.sort((a,e)=>e.score-a.score);return m.slice(0,d).map(a=>({...a.doc,score:a.score.toFixed(4)}))}}window.CustomSearchEngine=CustomSearchEngine;
